// Checks this package against the vectors generated by the Rust crate (spec/vectors/).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { API_VERSION, FORMAT_VERSION, LABEL_PREFIX, label } from "../src/index.js";

const vectors = (name) => JSON.parse(readFileSync(new URL(`../../../spec/vectors/${name}`, import.meta.url), "utf8"));

test("format version and label prefix match the Rust crate", () => {
  const meta = vectors("meta.json");
  assert.equal(FORMAT_VERSION, meta.format_version);
  assert.equal(LABEL_PREFIX, meta.label_prefix);
  assert.equal(API_VERSION, meta.api_version);
});

test("labels match the Rust crate", () => {
  for (const { purpose, label: expected } of vectors("meta.json").labels) {
    assert.equal(label(purpose, FORMAT_VERSION), expected);
  }
});

test("the label registry in spec/SPEC.md is exactly the labels in meta.json", () => {
  const spec = readFileSync(new URL("../../../spec/SPEC.md", import.meta.url), "utf8");
  const inSpec = new Set(spec.match(/rootcard\/[a-z0-9/]*[a-z0-9]\/v[0-9]+/g));
  const inMeta = new Set(vectors("meta.json").labels.map((l) => l.label));
  assert.deepEqual([...inSpec].sort(), [...inMeta].sort());
});

test("labels are unique and never contain a zero byte (SPEC DS-1, DS-2)", () => {
  const labels = vectors("meta.json").labels.map((l) => l.label);
  assert.equal(new Set(labels).size, labels.length);
  for (const l of labels) assert.match(l, /^rootcard\/[a-z]+(\/[a-z]+)*\/v[0-9]+$/);
});

// Every generated vector file (SPEC §21): run the operation and compare the output, or the error code, exactly.
import { createHash } from "node:crypto";
import { ops, setSha256Sync } from "./ops.mjs";

setSha256Sync((m) => new Uint8Array(createHash("sha256").update(m).digest()));
import { canonicalString, RootcardError } from "../src/index.js";

for (const file of ["primitives.json", "log.json", "vault.json", "profile.json", "proof.json", "file.json", "link.json"]) {
  const { vectors: list } = vectors(file);
  for (const v of list) {
    test(`${file}: ${v.name} [${v.rules.join(", ")}]`, async () => {
      const op = ops[v.op];
      assert.ok(op, `no operation ${v.op}`);
      let out;
      try {
        out = await op(v.input);
      } catch (e) {
        if (!(e instanceof RootcardError)) throw e;
        assert.equal(e.code, v.error ?? "(no error)", `unexpected error ${e.code}`);
        return;
      }
      assert.equal(v.error, undefined, `expected ${v.error}, got output`);
      assert.equal(canonicalString(out), canonicalString(v.output));
    });
  }
}
